    if (signal.aborted) {
      privateKey.fill(0)
      return undefined
    }
    const lease = new OwnedSshIdentityLease(path, privateKey, () => {
      this.activeLeases.delete(lease)
    })
    this.activeLeases.add(lease)
    return lease
  }
}

