#define _GNU_SOURCE

#include <errno.h>
#include <fcntl.h>
#include <node_api.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#if defined(__APPLE__)
#include <sys/stdio.h>
#elif defined(__linux__)
#include <sys/syscall.h>
#ifndef RENAME_NOREPLACE
#define RENAME_NOREPLACE (1 << 0)
#endif
#endif

#define HVIR_MAX_BASENAME_BYTES 255

static napi_value hvir_metadata(napi_env env, napi_callback_info info) {
  (void) info;
  napi_value result;
  if (napi_create_string_utf8(
        env,
        "hvir.rename-noreplace.v1",
        NAPI_AUTO_LENGTH,
        &result
      ) != napi_ok) {
    return NULL;
  }
  return result;
}

static int hvir_read_basename(napi_env env, napi_value value, char **output) {
  size_t length = 0;
  if (napi_get_value_string_utf8(env, value, NULL, 0, &length) != napi_ok
      || length == 0
      || length > HVIR_MAX_BASENAME_BYTES) {
    return EINVAL;
  }
  char *buffer = (char *) malloc(length + 1);
  if (buffer == NULL) return ENOMEM;
  size_t written = 0;
  if (napi_get_value_string_utf8(env, value, buffer, length + 1, &written) != napi_ok
      || written != length
      || memchr(buffer, '\0', length) != NULL
      || strchr(buffer, '/') != NULL
      || strcmp(buffer, ".") == 0
      || strcmp(buffer, "..") == 0) {
    free(buffer);
    return EINVAL;
  }
  *output = buffer;
  return 0;
